INSERT INTO approved_loans_archive (application_id, applicant_name, approved_amount_rounded, days_to_approval)
SELECT application_id, applicant_name, (FLOOR(requested_amount / 1000) * 1000)::DECIMAL(12,2), (approval_date - submission_date)
FROM loan_applications
WHERE status = 'approved' AND approval_date IS NOT NULL;

SELECT * FROM approved_loans_archive ORDER BY application_id;
